DECLARE total INT64 DEFAULT 0;
BEGIN TRANSACTION;
SET total = (SELECT COUNT(*) FROM ds.t);
IF total > 10 THEN
  INSERT INTO ds.log (n) VALUES (total);
ELSEIF total = 0 THEN
  RAISE USING MESSAGE = 'empty';
END IF;
WHILE total > 0 DO
  SET total = total - 1;
END WHILE;
MERGE ds.target T USING ds.source S ON T.id = S.id
WHEN MATCHED THEN UPDATE SET v = S.v
WHEN NOT MATCHED THEN INSERT (id, v) VALUES (S.id, S.v);
COMMIT TRANSACTION;
SELECT * FROM t QUALIFY ROW_NUMBER() OVER (PARTITION BY k ORDER BY ts DESC) = 1;
